<?php declare(strict_types=1); ?>
<?php if($errors): ?><div class="alert"><?= kd_e(implode(' ',$errors)) ?></div><?php endif; ?><?php if($success): ?><div class="settings-success"><?= kd_e($success) ?></div><?php endif; ?>
<div class="marketplace-grid"><section class="panel customer-form-panel"><h3>SMTP e-posta ayarları</h3><p class="muted">SMTP parolası sunucu üzerinde şifrelenerek saklanır. Parola alanını boş bırakırsanız kayıtlı parola korunur.</p><form method="post"><?= kd_csrf_field() ?><input type="hidden" name="form_action" value="settings"><div class="customer-fields"><label>SMTP sunucusu<input name="smtp_host" required value="<?= kd_e($settings['smtp_host']) ?>"></label><label>Port<input type="number" name="smtp_port" min="1" max="65535" value="<?= (int)$settings['smtp_port'] ?>"></label><label>Şifreleme<select name="smtp_encryption"><option value="tls" <?= $settings['smtp_encryption']==='tls'?'selected':'' ?>>STARTTLS</option><option value="ssl" <?= $settings['smtp_encryption']==='ssl'?'selected':'' ?>>SSL</option><option value="none" <?= $settings['smtp_encryption']==='none'?'selected':'' ?>>Yok</option></select></label><label>Kullanıcı adı<input name="smtp_username" value="<?= kd_e($settings['smtp_username']) ?>"></label><label>SMTP parolası<input type="password" name="smtp_password" autocomplete="new-password"></label><label>Gönderen e-posta<input type="email" name="from_email" required value="<?= kd_e($settings['from_email']) ?>"></label><label class="field-wide">Gönderen adı<input name="from_name" required value="<?= kd_e($settings['from_name']) ?>"></label></div><button class="btn primary">SMTP ayarlarını kaydet</button></form></section>
<section class="panel customer-form-panel"><h3>Mesaj şablonu</h3><p class="muted">E-posta, SMS ve WhatsApp mesajları için tekrar kullanılabilir metinler oluşturun.</p><form method="post"><?= kd_csrf_field() ?><input type="hidden" name="form_action" value="template"><label>Şablon anahtarı<input name="template_key" placeholder="order_confirmed" required pattern="[a-z0-9_.-]{3,100}"></label><label>Şablon adı<input name="name" required></label><label>Kanal<select name="channel"><option value="email">E-posta</option><option value="sms">SMS</option><option value="whatsapp">WhatsApp</option></select></label><label>Konu<input name="subject"></label><label>Mesaj metni<textarea name="body" rows="5" required></textarea></label><button class="btn secondary">Şablonu kaydet</button></form></section></div>
<section class="panel customer-form-panel"><h3>E-posta gönder</h3><form method="post"><?= kd_csrf_field() ?><input type="hidden" name="form_action" value="send"><div class="customer-fields"><label>Alıcı e-posta<input type="email" name="recipient" required></label><label>Konu<input name="subject" required></label><label class="field-wide">Mesaj<textarea name="body" rows="5" required></textarea></label></div><button class="btn primary">E-postayı gönder</button></form></section>
<section class="panel customer-list-panel"><div class="panel-head"><h3>Mesaj şablonları</h3><span class="result-count"><?= count($templates) ?> şablon</span></div><div class="table-wrap"><table class="data-table"><thead><tr><th>Anahtar</th><th>Ad</th><th>Kanal</th><th>Konu</th><th>Durum</th></tr></thead><tbody><?php foreach($templates as $t): ?><tr><td><?= kd_e($t['template_key']) ?></td><td><?= kd_e($t['name']) ?></td><td><?= kd_e($t['channel']) ?></td><td><?= kd_e($t['subject']) ?></td><td><?= kd_e($t['status']) ?></td></tr><?php endforeach; ?><?php if(!$templates): ?><tr><td colspan="5">Şablon bulunmuyor.</td></tr><?php endif; ?></tbody></table></div></section>
<section class="panel customer-list-panel"><div class="panel-head"><h3>Gönderim geçmişi</h3><span class="result-count"><?= count($logs) ?> kayıt</span></div><div class="table-wrap"><table class="data-table"><thead><tr><th>Tarih</th><th>Kanal</th><th>Alıcı</th><th>Konu</th><th>Durum</th><th>Yanıt</th></tr></thead><tbody><?php foreach($logs as $l): ?><tr><td><?= kd_e(date('d.m.Y H:i',strtotime($l['created_at']))) ?></td><td><?= kd_e($l['channel']) ?></td><td><?= kd_e($l['recipient']) ?></td><td><?= kd_e($l['subject']) ?></td><td><?= kd_e($l['status']) ?></td><td><?= kd_e($l['provider_response']) ?></td></tr><?php endforeach; ?><?php if(!$logs): ?><tr><td colspan="6">Gönderim kaydı yok.</td></tr><?php endif; ?></tbody></table></div></section>
